insert into public.country_occupation_metric_snapshots (profile_key,as_of_date,shortage_component,vacancy_intensity_component,employer_diversity_component,vacancy_trend_component,entry_level_component,salary_component,growth_component,visa_component,entry_burden_component,opportunity_score,score_methodology_version,score_status,score_evidence,source_checked_at) values
('JP:registered-nurse','2026-08-10',0,0,0,0,10,0,0,0,1,11,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','The 2022 MHLW classification splits 看護師・准看護師 by workplace under 023-01/02/03/99; the canonical Registered Nurse profile is restricted to 看護師 and therefore does not claim one exact small-classification code.','entry_level_basis','Approved Japanese nursing programmes are retained as direct study pathways, but completion alone is not a nursing licence.','qualification_note','A 看護師 must pass the national examination and obtain the Minister of Health, Labour and Welfare licence.','market_scope','No exact registered-nurse-only recurring comparable market series has been normalised across the workplace codes.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-10'),
('JP:midwife','2026-08-10',0,0,0,0,8,0,0,0,1,9,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','2022 MHLW 022-02 directly classifies 助産師.','entry_level_basis','Midwifery requires a regulated education and examination pathway; no approved CampCareer Japan programme link is currently published for this canonical career.','qualification_note','A 助産師 must pass both the midwife and nurse national examinations and obtain the ministerial licence.','market_scope','No exact recurring comparable 022-02 labour-market series has been normalised.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-10'),
('JP:care-worker','2026-08-10',0,0,0,0,15,0,0,0,5,20,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','The canonical Care Worker spans facility care 050-01/02/03/99 and home-care 051-01/02 rather than one exact 2022 MHLW small classification.','entry_level_basis','Facility-care entry can occur without a specific academic credential, while training such as 介護職員初任者研修 and the national 介護福祉士 qualification can strengthen or be required for particular service responsibilities.','qualification_note','介護福祉士 is a protected national title, but the broad care-worker occupation is not universally licensed; home-care service roles can have separate training requirements.','market_scope','Facility and home-care groups are not merged into a fabricated single market series.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-10'),
('JP:physiotherapist','2026-08-10',0,0,0,0,10,0,0,0,1,11,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','2022 MHLW 024-04 directly classifies 理学療法士.','entry_level_basis','An approved Japanese physical-therapy programme is retained as a direct study pathway, subject to the statutory education and national-examination requirements.','qualification_note','A 理学療法士 must pass the national examination and obtain the Minister of Health, Labour and Welfare licence.','market_scope','No exact recurring comparable 024-04 market series is scored.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-10'),
('JP:medical-laboratory-technician','2026-08-10',0,0,0,0,10,0,0,0,1,11,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','2022 MHLW 024-03 directly classifies 臨床検査技師.','entry_level_basis','An approved Japanese medical-laboratory-science programme is retained as a direct study pathway; programme completion is not itself the professional licence.','qualification_note','Clinical laboratory technologists are licensed under the 臨床検査技師等に関する法律 after the national examination.','market_scope','No exact recurring comparable 024-03 market series is scored.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-10'),
('JP:radiographer','2026-08-10',0,0,0,0,10,0,0,0,1,11,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','2022 MHLW 024-01 directly classifies 診療放射線技師.','entry_level_basis','An approved Japanese radiological-technology programme is retained as a direct study pathway, subject to the statutory training and examination pathway.','qualification_note','A 診療放射線技師 must pass the national examination and obtain the Minister of Health, Labour and Welfare licence.','market_scope','No exact recurring comparable 024-01 market series is scored.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-10'),
('JP:pharmacist','2026-08-10',0,0,0,0,8,0,0,0,1,9,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','2022 MHLW 021-04 directly classifies 薬剤師.','entry_level_basis','An approved Japanese pharmacy programme is retained as a direct study pathway, but statutory educational eligibility and the national examination remain decisive.','qualification_note','A 薬剤師 must pass the national examination and obtain the Minister of Health, Labour and Welfare licence.','market_scope','No exact recurring comparable 021-04 market series is scored.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-10'),
('JP:occupational-therapist','2026-08-10',0,0,0,0,10,0,0,0,1,11,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','2022 MHLW 024-05 directly classifies 作業療法士.','entry_level_basis','An approved Japanese occupational-therapy programme is retained as a direct study pathway, subject to statutory education and national-examination requirements.','qualification_note','A 作業療法士 must pass the national examination and obtain the Minister of Health, Labour and Welfare licence.','market_scope','No exact recurring comparable 024-05 market series is scored.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-10')
